import pandas as pd

def compute_signal(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy().sort_values(["permno", "time_avail_m"])
    prior_volume = df.groupby("permno")["mthvol"].shift(1)
    df["average_prior_volume"] = (
        prior_volume.groupby(df["permno"])
        .rolling(3, min_periods=3)
        .mean()
        .reset_index(level=0, drop=True)
    )
    df["signal"] = 100 * df["average_prior_volume"] / (1000 * df["shrout"])
    df = df[df["signal"].notna() & (df["shrout"] > 0)]
    df = df[df["signal"].replace([float("inf"), float("-inf")], pd.NA).notna()]
    return df[["permno", "time_avail_m", "signal"]].rename(
        columns={"time_avail_m": "yyyymm"}
    )
